@implementation PetView
-(void)drawRect:(NSRect)rect {NSImage *image=[[NSImage alloc]initWithContentsOfURL:[NSBundle.mainBundle URLForResource:@"moss" withExtension:@"png"]];NSGraphicsContext.currentContext.imageInterpolation=NSImageInterpolationNone;[image drawInRect:NSInsetRect(self.bounds,2,2)];}

-(void)mouseDown:(NSEvent*)e {self.start=NSEvent.mouseLocation;self.origin=self.window.frame.origin;self.moved=NO;}
-(void)mouseDragged:(NSEvent*)e {NSPoint p=NSEvent.mouseLocation;if(hypot(p.x-self.start.x,p.y-self.start.y)>3){self.moved=YES;[self.timer invalidate];[self.window setFrameOrigin:NSMakePoint(self.origin.x+p.x-self.start.x,self.origin.y+p.y-self.start.y)];}}
-(void)mouseUp:(NSEvent*)e {if(self.moved)return;if(e.clickCount==2){[self.timer invalidate];[controller showNotes];}else{self.timer=[NSTimer scheduledTimerWithTimeInterval:NSEvent.doubleClickInterval repeats:NO block:^(NSTimer*t){[controller showQuick];}];}}
-(void)rightMouseDown:(NSEvent*)e {NSMenu*m=[NSMenu new];[m addItemWithTitle:@"打开 Sneakkkkk" action:@selector(showNotes) keyEquivalent:@""];[m addItemWithTitle:@"退出" action:@selector(terminate:) keyEquivalent:@"q"];[NSMenu popUpContextMenu:m withEvent:e forView:self];}
@end
